rows={(r['date'],r['plant']):r for r in csv.DictReader(open('root-price-history.csv'))}
f=lambda x: None if x in ('',None) else float(x)
DEF={'TN':100.0,'PM':100.0,'TDC':100.0,'MS':100.0,'TKT':95.0}
n=0
for k,v in SRC.items():
    d,p=k[:2],k[2:]; r=rows[('2026-11-'+d,p)]
    vol,pr,st,rec,cag=[f(x) for x in v[:5]]
    if vol is None: pr=st=rec=cag=None
    if rec in (None,0.0) or rec==DEF[p]:
        if not(p=='TKT' and rec==95.0 and not (f(v[5])==95.0 and f(v[6])==95.0)): rec=cag=None
    if rec is None: cag=None
    src=(pr,vol,st,cag,rec)
    cur=tuple(f(r[c]) for c in ['price_thb_kg','volume_tons','starch_pct','cag_thb_kg','recovery_pct'])
    if src!=cur: n+=1; print('DIFF',d,p,'src',src,'csv',cur)
    if rec and pr and st:
        c2=pr/(st/100)/(rec/100)
        if abs(c2-cag)>0.06: print('FORMULA?',d,p,c2,cag)
print('diffs',n)
